def test_large():
    orders = [{"sku": f"s{i % 50_000:05d}", "qty": (i % 7) + 1, "unit_price_cents": (i % 1000) + 1} for i in range(200_000)]
    result = top_k_products(orders, 3)
    totals = {}
    for o in orders:
        totals[o["sku"]] = totals.get(o["sku"], 0) + o["qty"] * o["unit_price_cents"]
    expected = sorted(totals.items(), key=lambda kv: (-kv[1], kv[0]))[:3]
    assert result == expected

