import heapq
from collections import defaultdict


def top_k_products(orders: list[dict], k: int) -> list[tuple[str, int]]:
    revenue: dict[str, int] = defaultdict(int)
    for line in orders:
        revenue[line["sku"]] += line["qty"] * line["unit_price_cents"]
    return heapq.nsmallest(k, revenue.items(), key=lambda kv: (-kv[1], kv[0]))
